import{_ as a,o as t,c as n,h as i}from"./chunks/framework.DC5NoOP7.js";const p=JSON.parse('{"title":"Teaching AI","description":"Keith Williams teaches practical AI literacy and software engineering through hands-on projects, specifications, testing, and human judgment.","frontmatter":{"title":"Teaching AI","description":"Keith Williams teaches practical AI literacy and software engineering through hands-on projects, specifications, testing, and human judgment."},"headers":[],"relativePath":"teaching.md","filePath":"teaching.md"}'),o={name:"teaching.md"};function r(s,e,l,h,c,d){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="teaching-ai" tabindex="-1">Teaching AI <a class="header-anchor" href="#teaching-ai" aria-label="Permalink to &quot;Teaching AI&quot;">​</a></h1><p><strong>AI literacy is not just knowing which button to click.</strong> It is learning how to frame a problem, direct a capable tool, evaluate its results, and remain responsible for the outcome.</p><p>I&#39;m Keith Williams, a Senior University Lecturer at NJIT. My teaching combines software engineering, instructional design, and hands-on learning. The practical question is: <strong>What do people need to know and do when AI can already perform many of the steps for them?</strong></p><h2 id="from-using-ai-to-understanding-it" tabindex="-1">From using AI to understanding it <a class="header-anchor" href="#from-using-ai-to-understanding-it" aria-label="Permalink to &quot;From using AI to understanding it&quot;">​</a></h2><p>A useful AI learning experience should help someone:</p><ul><li><strong>Frame the problem:</strong> identify the people involved, constraints, requirements, and desired outcome.</li><li><strong>Build a working artifact:</strong> use AI where it helps, but understand the major design choices.</li><li><strong>Evaluate the result:</strong> run tests, examine the evidence, and question the model&#39;s assumptions.</li><li><strong>Explain and transfer learning:</strong> show the reasoning behind the work and apply it in a new situation.</li></ul><p>The goal is not to make people dependent on one model or interface. It is to develop the judgment to work with changing tools.</p><h2 id="what-this-looks-like-in-practice" tabindex="-1">What this looks like in practice <a class="header-anchor" href="#what-this-looks-like-in-practice" aria-label="Permalink to &quot;What this looks like in practice&quot;">​</a></h2><h3 id="spec-driven-software-development" tabindex="-1">Spec-driven software development <a class="header-anchor" href="#spec-driven-software-development" aria-label="Permalink to &quot;Spec-driven software development&quot;">​</a></h3><p>I use clear project requirements, personas, acceptance criteria, and reviews to connect ideas to testable work. Students work with repositories, documented decisions, and the evidence needed to evaluate what was built.</p><h3 id="ai-assisted-learning-studios" tabindex="-1">AI-assisted learning studios <a class="header-anchor" href="#ai-assisted-learning-studios" aria-label="Permalink to &quot;AI-assisted learning studios&quot;">​</a></h3><p>The <a href="https://github.com/kaw393939/is117-brand-studio" target="_blank" rel="noreferrer">IS117 Brand Studio</a> is a public teaching template in which students turn a neutral T-shirt storefront into a brand. It combines hands-on changes, an evolving style guide, and reflection on decisions. The storefront is an educational demonstration, <strong>not</strong> a commercial checkout.</p><h3 id="reusable-learning-systems" tabindex="-1">Reusable learning systems <a class="header-anchor" href="#reusable-learning-systems" aria-label="Permalink to &quot;Reusable learning systems&quot;">​</a></h3><p>The <a href="https://kaw393939.github.io/educational-design-system/" target="_blank" rel="noreferrer">Educational Design System</a> explores repeatable structures for educational content and websites. Its published first-phase foundation includes shared design tokens, layouts, pedagogical components, and release checks; later phases remain work in progress.</p><h2 id="beyond-the-classroom" tabindex="-1">Beyond the classroom <a class="header-anchor" href="#beyond-the-classroom" aria-label="Permalink to &quot;Beyond the classroom&quot;">​</a></h2><p>AI education should be understandable to students, educators, professionals, and curious people outside the university. My <a href="https://github.com/kaw393939/everyday-ai-cli" target="_blank" rel="noreferrer">Everyday AI CLI</a> is one example of making practical AI workflows more approachable through repeatable tools. It is a published alpha, not a claim that every integration is production-ready.</p><h2 id="the-connection-to-research" tabindex="-1">The connection to research <a class="header-anchor" href="#the-connection-to-research" aria-label="Permalink to &quot;The connection to research&quot;">​</a></h2><p>Teaching raises questions that cannot be answered by a working demonstration alone: How do we know someone has learned? What happens when AI produces the final artifact? How do we evaluate independent judgment?</p><p>Those questions lead to the second half of this work: <a href="/research">Rethinking education with AI</a>.</p><hr><p><strong>Explore the evidence:</strong> <a href="/#projects">Selected projects</a> · <a href="https://people.njit.edu/profile/kwilliam" target="_blank" rel="noreferrer">NJIT faculty profile</a> · <a href="/#conversation">Start a public conversation</a></p><p><em>This is a personal description of my educational approach, not an official NJIT curriculum statement or a claim of measured learning gains.</em></p>',22)])])}const g=a(o,[["render",r]]);export{p as __pageData,g as default};
